const getTrainingStreak = (dates: string[]) => {
 const completed = new Set(dates);
 const today = new Date();
 today.setHours(0,0,0,0);
 const key = (date: Date) => date.toLocaleDateString("en-CA");
 let start = new Date(today);
 if (!completed.has(key(start))) start.setDate(start.getDate()-1);
 let streak = 0;
 while (completed.has(key(start)) && streak < 365) {
  streak++;
  start.setDate(start.getDate()-1);
 }
 return streak;
};
const getLongestTrainingStreak = (dates: string[]) => {
 const ordered = [...new Set(dates)].sort();
 let best = 0;
 let current = 0;
 let previous: Date | null = null;
 ordered.forEach(key => {
  const date = new Date(key+"T00:00:00");
  if (previous) {
   const expected = new Date(previous);
   expected.setDate(expected.getDate()+1);
   current = date.getTime()===expected.getTime()?current+1:1;
  } else current = 1;
  best = Math.max(best,current);
  previous = date;
 });
 return best;
};
