 {phase==="Listo"&&<TouchableOpacity style={styles.primary} onPress={()=>{setRepCount(0);setPhase("Trabajo");setSecondsLeft(workout[exerciseIndex].kind==="time"?workout[exerciseIndex].work:0);if(workout[exerciseIndex].kind==="time")setTimerRunning(true);else setPhase("Trabajo")}}><Text style={styles.primaryText}>{workout[exerciseIndex].kind==="time"?"INICIAR TEMPORIZADOR":"COMENZAR SERIE"}</Text><Ionicons name="play" size={17} color={C.bg}/></TouchableOpacity>}
 {phase==="Trabajo"&&workout[exerciseIndex].kind==="reps"&&<><View style={{alignItems:"center",marginTop:18}}><Text style={styles.eyebrow}>REPETICIONES COMPLETADAS</Text><Text style={styles.bigNumber}>{repCount} / {workout[exerciseIndex].reps}</Text><View style={{flexDirection:"row",gap:12,marginTop:10}}><TouchableOpacity style={styles.secondaryButton} onPress={()=>setRepCount(n=>Math.max(0,n-1))}><Text style={styles.secondaryButtonText}>− UNA</Text></TouchableOpacity><TouchableOpacity style={[styles.primary,{marginTop:0,flex:1}]} onPress={()=>setRepCount(n=>Math.min(workout[exerciseIndex].reps,n+1))}><Text style={styles.primaryText}>+ UNA REPETICIÓN</Text></TouchableOpacity></View></View><TouchableOpacity disabled={repCount<workout[exerciseIndex].reps} style={[styles.primary,repCount<workout[exerciseIndex].reps&&{opacity:0.35}]} onPress={()=>{setPhase("Descanso");setSecondsLeft(currentRest);setTimerRunning(true)}}><Text style={styles.primaryText}>TERMINÉ LAS REPETICIONES</Text><Ionicons name="checkmark" size={18} color={C.bg}/></TouchableOpacity>{repCount<workout[exerciseIndex].reps&&<Text style={[styles.cardSub,{textAlign:"center",marginTop:8}]}>Completa las {workout[exerciseIndex].reps} repeticiones para continuar ({workout[exerciseIndex].reps-repCount} restantes).</Text>}</>}
 {phase==="Trabajo"&&workout[exerciseIndex].kind==="time"&&<TouchableOpacity style={styles.secondaryButton} onPress={()=>{setTimerRunning(false);setPhase("Descanso");setSecondsLeft(currentRest);setTimerRunning(true)}}><Text style={styles.secondaryButtonText}>FINALIZAR ANTES</Text></TouchableOpacity>}
 {((phase==="Descanso"&&secondsLeft>0)||(phase==="Trabajo"&&workout[exerciseIndex].kind==="time"))&&<TouchableOpacity style={styles.secondaryButton} onPress={()=>setTimerRunning(running=>!running)}><Text style={styles.secondaryButtonText}>{timerRunning?"PAUSAR TEMPORIZADOR":"REANUDAR TEMPORIZADOR"}</Text></TouchableOpacity>}
 {phase==="Descanso"&&secondsLeft>0&&<View style={{flexDirection:"row",justifyContent:"center",gap:12,marginTop:10}}><TouchableOpacity style={styles.secondaryButton} onPress={()=>setSecondsLeft(n=>Math.max(1,n-10))}><Text style={styles.secondaryButtonText}>− 10 SEGUNDOS</Text></TouchableOpacity><TouchableOpacity style={styles.secondaryButton} onPress={()=>setSecondsLeft(n=>Math.min(600,n+10))}><Text style={styles.secondaryButtonText}>+ 10 SEGUNDOS</Text></TouchableOpacity></View>}
 {phase==="Descanso"&&<TouchableOpacity style={styles.primary} onPress={()=>{setTimerRunning(false);if(series<workout[exerciseIndex].sets){setSeries(series+1);setRepCount(0);setPhase("Listo");setSecondsLeft(workout[exerciseIndex].work)}else if(exerciseIndex<workout.length-1){const next=exerciseIndex+1;setExerciseIndex(next);setSeries(1);setRepCount(0);setPhase("Listo");setSecondsLeft(workout[next].work)}else{setPhase("Completado");setCompletedSessions(n=>n+1);setWorkoutDates(old=>[...new Set([new Date().toLocaleDateString("en-CA"),...old])].sort().reverse().slice(0,365));setWorkoutHistory(old=>[{date:new Date().toLocaleDateString("en-CA"),level:experience,exercises:workout.length,sets:workout.reduce((total,item)=>total+item.sets,0)},...old].slice(0,50));setSecondsLeft(0)}}}><Text style={styles.primaryText}>{series<workout[exerciseIndex].sets?"SIGUIENTE SERIE":exerciseIndex<workout.length-1?"SIGUIENTE EJERCICIO":"TERMINAR ENTRENAMIENTO"}</Text><Ionicons name="arrow-forward" size={18} color={C.bg}/></TouchableOpacity>}
 <TouchableOpacity style={styles.secondaryButton} onPress={()=>{setTimerRunning(false);setPhase("Listo");setSeries(1);setRepCount(0);setSecondsLeft(workout[exerciseIndex].work)}}><Text style={styles.secondaryButtonText}>REINICIAR EJERCICIO</Text></TouchableOpacity>
 {phase!=="Completado"&&exerciseIndex<workout.length-1&&<TouchableOpacity style={styles.secondaryButton} onPress={()=>{const next=exerciseIndex+1;setTimerRunning(false);setExerciseIndex(next);setSeries(1);setRepCount(0);setPhase("Listo");setSecondsLeft(workout[next].work)}}><Text style={styles.secondaryButtonText}>OMITIR EJERCICIO</Text></TouchableOpacity>}
